import { Quiz } from "./Quiz.jsx";

const preguntas = [
  {
    texto: "¿Cuál es la capital del Perú?",
    opciones: ["Cusco", "Lima", "Arequipa"],
    correcta: "Lima",
  },
  {
    texto: "¿Qué devuelve typeof null en JavaScript?",
    opciones: ["null", "undefined", "object"],
    correcta: "object",
  },
  {
    texto: "¿Qué hook usas para guardar estado en React?",
    opciones: ["useState", "useEffect", "useRef"],
    correcta: "useState",
  },
  {
    texto: "¿Qué método de array devuelve un arreglo nuevo con los elementos que cumplen una condición?",
    opciones: ["map", "filter", "forEach"],
    correcta: "filter",
  },
];

export default function App() {
  return (
    <main style={{ maxWidth: 480, margin: "2rem auto", fontFamily: "system-ui, sans-serif" }}>
      <h1>Quiz rápido</h1>
      <Quiz preguntas={preguntas} />
    </main>
  );
}
